import{_ as e,o as a,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"2020-02-27 -- Ceph Performance Meeting","description":"","frontmatter":{"title":"2020-02-27 -- Ceph Performance Meeting","date":"2020-02-27T00:00:00.000Z","updated":"2020-04-04T00:00:00.000Z","tags":["Ceph","性能优化","分布式存储","BlueStore","IO 500"],"categories":["会议纪要"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/2020-02-27_-_-_Ceph_Performance_Meeting.md","filePath":"posts/2020/2020-02-27_-_-_Ceph_Performance_Meeting.md","lastUpdated":1780460162000}'),r={name:"posts/2020/2020-02-27_-_-_Ceph_Performance_Meeting.md"};function o(n,l,s,h,u,d){return a(),i("div",null,[...l[0]||(l[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议时间" tabindex="-1">会议时间 <a class="header-anchor" href="#会议时间" aria-label="Permalink to &quot;会议时间&quot;">​</a></h4><ul><li>日期：2020年2月27日</li><li>时间：上午</li></ul><h4 id="参会人员" tabindex="-1">参会人员 <a class="header-anchor" href="#参会人员" aria-label="Permalink to &quot;参会人员&quot;">​</a></h4><ul><li>Mark</li><li>Igor</li><li>Radek</li><li>David Stockman</li><li>Patrick</li><li>其他相关人员</li></ul><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>Ceph文件系统深度剖析文档</strong></p><ul><li>Mark确认存在一份95页的Ceph文件系统深度剖析文档，尽管部分细节可能已过时，但整体架构未变。</li></ul></li><li><p><strong>本周PR更新</strong></p><ul><li>Igor提交了一个PR，增加分配统计信息以进行性能测试。</li><li>Radek关闭了一个关于缓冲区列表的小改动PR。</li><li>Igor的一个关于BlueStore自动调优的PR被关闭，不再相关。</li><li>Mark更新了混合分配器和内存减少的PR，等待审查。</li></ul></li><li><p><strong>IO 500测试进展</strong></p><ul><li>Ceph在IO 500测试中排名第12，接近第11。</li><li>讨论了MDS中的锁争用问题，并尝试通过改进锁机制优化性能。</li></ul></li><li><p><strong>管理器性能问题</strong></p><ul><li>用户报告了管理器性能缓慢和CPU使用率高的问题。</li><li>通过gdb pmp分析，发现主要时间花费在dump OST stats和PG stats上。</li><li>David Stockman提交了一个PR，优化统计信息的获取方式。</li></ul></li><li><p><strong>其他讨论</strong></p><ul><li>讨论了将PR合并到Octopus版本中，特别是关于混合分配器和内存减少的PR。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>同意合并混合分配器和内存减少的PR，但暂时不改变默认设置。</li><li>继续优化管理器的性能问题。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>Igor将继续调查顺序读取性能问题，并在Archer集群上进行更多测试。</li><li>团队将继续优化IO 500测试中的表现，特别是MDS的锁争用问题。</li><li>管理器的性能优化PR将尽快合并，并观察其效果。</li></ul><h4 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h4><ul><li>会议在大家互相道别后结束，期待下周的会议。</li></ul>',13)])])}const c=e(r,[["render",o]]);export{p as __pageData,c as default};
